/// <summary>
/// Extension class of the SysListPanel class. Used to add the up and down button during build, as this is not an option in the standard class.
/// </summary>
[ExtensionOf(classStr(SysListPanel))]
final class SysListPanel_Extension
{
}

Method.Source:
/// <summary>
/// Add the up and down button during build when initiated from the TFMMenuConfig form, as this is not an option in the standard class.
/// </summary>
public void build()
{
    if (formRun.name() == formStr(TFMMenuConfig))
    {
        hasUpDownButton = true;
    }
    next Build();
}
